import unittest

from solution import normalize_route


class NormalizeRouteTests(unittest.TestCase):
    def test_normalizes_and_sorts(self):
        route = "  Zebra / a! / bb / Ant / c  "
        self.assertEqual(normalize_route(route), "a!/c/bb/Ant/Zebra")

    def test_preserves_spelling_punctuation_and_stability(self):
        self.assertEqual(
            normalize_route(" b / A / a / B / ! "),
            "!/A/a/b/B",
        )
        self.assertEqual(normalize_route(" x / X / x "), "x/X/x")

    def test_empty_input(self):
        self.assertEqual(normalize_route(""), "")
        self.assertEqual(normalize_route(" \t\n "), "")

    def test_empty_labels_are_rejected(self):
        for route in ("/a", "a/", "a//b", "a/   /b", "/"):
            with self.subTest(route=route):
                with self.assertRaises(ValueError):
                    normalize_route(route)

    def test_non_string_is_rejected(self):
        for value in (None, 3, ["a", "b"]):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    normalize_route(value)


if __name__ == "__main__":
    unittest.main()

